frappe.web_form.after_load = () => {
    const path = window.location.pathname.replace(/\/$/, "");

    // === New record: resolve the linked Customer, then redirect to their edit page ===
    if (path === "/update-customer-details/new") {
        frappe.call({
            method: "get_portal_party",
            args: {
                party_type: "Customer"
            },
            callback: function (r) {
                const row = r.message?.[0];

                if (!row) {
                    frappe.msgprint(
                        __("No Customer record is linked to your user account.")
                    );
                    return;
                }

                if (row.party_type !== "Customer") {
                    frappe.msgprint(
                        __("Unexpected party type returned for this page.")
                    );
                    return;
                }

                window.location.href =
                    "/update-customer-details/" + encodeURIComponent(row.party);
            },
            error: function () {
                frappe.msgprint(
                    __("Could not load your Customer details. Please try again.")
                );
            }
        });
        return;
    }

    // === Editing an existing record: show "Editing: <Company Name>" heading ===
    const companyName = frappe.web_form.doc.customer_name;

    // Guard: only touch the heading field if it actually exists on this
    // Web Form. Prevents a missing/misnamed field from throwing and
    // breaking the rest of after_load.
    const headingFieldExists = !!frappe.web_form.fields_dict?.heading_html;

    if (companyName && headingFieldExists) {
        frappe.web_form.set_df_property(
            "heading_html",
            "options",
            `<h4>Editing: ${frappe.utils.escape_html(companyName)}</h4>`
        );
    } else if (companyName && !headingFieldExists) {
        // Field not configured on this Web Form — log for the developer,
        // don't break the page for the portal user.
        console.warn(
            'get_portal_party: "heading_html" field not found on this Web Form — heading not set.'
        );
    }
};

frappe.web_form.after_load = () => {
    const path = window.location.pathname.replace(/\/$/, "");

    // === New record: resolve the linked Supplier, then redirect to their edit page ===
    if (path === "/update-supplier-details/new") {
        frappe.call({
            method: "get_portal_party",
            args: {
                party_type: "Supplier"
            },
            callback: function (r) {
                const row = r.message?.[0];

                if (!row) {
                    frappe.msgprint(
                        __("No Supplier record is linked to your user account.")
                    );
                    return;
                }

                if (row.party_type !== "Supplier") {
                    // Should be structurally impossible given the server-side
                    // filter, but guards against future breakage.
                    frappe.msgprint(
                        __("Unexpected party type returned for this page.")
                    );
                    return;
                }

                // Redirect by Supplier ID (party), never party_name/company
                // name — the web form resolves records by ID, and company
                // names aren't guaranteed unique.
                window.location.href =
                    "/update-supplier-details/" + encodeURIComponent(row.party);
            },
            error: function () {
                frappe.msgprint(
                    __("Could not load your Supplier details. Please try again.")
                );
            }
        });
        return;
    }

    // === Editing an existing record: show "Editing: <Company Name>" heading ===
    // frappe.web_form.doc is already populated at this point, since the
    // record was resolved from the URL segment by the web form itself —
    // no extra API call needed here.
    const companyName = frappe.web_form.doc.supplier_name;

    // Guard: only touch the heading field if it actually exists on this
    // Web Form. Prevents a missing/misnamed field from throwing and
    // breaking the rest of after_load (see: set_df_property "Cannot
    // read properties of undefined (reading 'df')" if field is absent).
    const headingFieldExists = !!frappe.web_form.fields_dict?.heading_html;

    if (companyName && headingFieldExists) {
        frappe.web_form.set_df_property(
            "heading_html",
            "options",
            `<h4>Editing: ${frappe.utils.escape_html(companyName)}</h4>`
        );
    } else if (companyName && !headingFieldExists) {
        // Field not configured on this Web Form — log for the developer,
        // don't break the page for the portal user.
        console.warn(
            'get_portal_party: "heading_html" field not found on this Web Form — heading not set.'
        );
    }
};

frappe.web_form.after_load = () => {
    // Determine the requested ledger type from the Web Form.
    // For a Customer ledger, use "Customer"; for a Supplier ledger,
    // use "Supplier".
    const partyType = frappe.web_form.get_value("party_type");

    // Require a valid party type before requesting ledger data.
    if (!["Customer", "Supplier"].includes(partyType)) {
        frappe.msgprint(
            __("Please select Customer or Supplier.")
        );
        return;
    }

    // Fetch ledger data from the server.
    // The server verifies that the requested party belongs to the
    // currently logged-in portal user.
    frappe.call({
        method: "get_portal_ledger",
        args: {
            party_type: partyType
        },
        callback: function (r) {
            const data = r.message;

            // Stop if the server returned no ledger context.
            if (!data) {
                frappe.msgprint(
                    __("Unable to load your ledger.")
                );
                return;
            }

            // The server-resolved party is authoritative.
            // Do not use a client-supplied party value here.
            console.log("Ledger Party:", data.party);
            console.log("Party Type:", data.party_type);
            console.log("Entries:", data.entries);
        }
    });
};
